// Разбор PNG-скриншота без зависимостей (zlib из Node): где в области экрана «чернила» текста — по строкам.
// Нужен, потому что Appium видит только рамку элемента, а не то, с какой стороны нарисован текст внутри поля (RTL, #7581cb).
import { readFile } from 'node:fs/promises';
import { inflateSync } from 'node:zlib';

/** PNG 8 бит, RGB/RGBA, без чересстрочности → { width, height, bpp, data (после снятия фильтров) }. */
export function decodePng(buf) {
  if (buf.readUInt32BE(0) !== 0x89504e47) throw new Error('Не PNG');
  let pos = 8, width = 0, height = 0, bitDepth = 0, colorType = 0, interlace = 0;
  const idat = [];
  while (pos < buf.length) {
    const len = buf.readUInt32BE(pos);
    const type = buf.toString('ascii', pos + 4, pos + 8);
    const body = buf.subarray(pos + 8, pos + 8 + len);
    if (type === 'IHDR') {
      width = body.readUInt32BE(0); height = body.readUInt32BE(4);
      bitDepth = body[8]; colorType = body[9]; interlace = body[12];
    } else if (type === 'IDAT') idat.push(body);
    else if (type === 'IEND') break;
    pos += 12 + len;
  }
  if (bitDepth !== 8 || ![2, 6].includes(colorType) || interlace) throw new Error(`Неподдерживаемый PNG: depth ${bitDepth}, color ${colorType}, interlace ${interlace}`);
  const bpp = colorType === 6 ? 4 : 3;
  const stride = width * bpp;
  const raw = inflateSync(Buffer.concat(idat));
  const data = Buffer.alloc(stride * height);
  for (let y = 0; y < height; y++) {
    const f = raw[y * (stride + 1)];
    const src = raw.subarray(y * (stride + 1) + 1, (y + 1) * (stride + 1));
    for (let x = 0; x < stride; x++) {
      const a = x >= bpp ? data[y * stride + x - bpp] : 0;
      const b = y > 0 ? data[(y - 1) * stride + x] : 0;
      const c = x >= bpp && y > 0 ? data[(y - 1) * stride + x - bpp] : 0;
      let v = src[x];
      if (f === 1) v += a;
      else if (f === 2) v += b;
      else if (f === 3) v += (a + b) >> 1;
      else if (f === 4) {
        const p = a + b - c, pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c);
        v += pa <= pb && pa <= pc ? a : pb <= pc ? b : c;
      }
      data[y * stride + x] = v & 255;
    }
  }
  return { width, height, bpp, data };
}

/**
 * Строки текста в прямоугольнике rect (в пунктах экрана): для каждой строки — отступы чернил от левого и правого края rect.
 * Фон = цвет пикселя у левого верхнего угла области (внутри rect, отступ 3 pt). «Чернила» — пиксели, заметно отличающиеся от фона.
 * Строки разделяются пустыми строками пикселей. Возвращает [{ leftGap, rightGap, top, bottom }] в пунктах.
 */
export async function inkLines(pngFile, rect, windowWidth) {
  const png = decodePng(await readFile(pngFile));
  const k = png.width / windowWidth; // пикселей на пункт
  const inset = 3;
  const x0 = Math.max(0, Math.round((rect.x + inset) * k)), x1 = Math.min(png.width, Math.round((rect.x + rect.width - inset) * k));
  const y0 = Math.max(0, Math.round((rect.y + inset) * k)), y1 = Math.min(png.height, Math.round((rect.y + rect.height - inset) * k));
  const px = (x, y) => { const i = (y * png.width + x) * png.bpp; return [png.data[i], png.data[i + 1], png.data[i + 2]]; };
  const bg = px(x0, y0);
  const isInk = (x, y) => { const p = px(x, y); return Math.abs(p[0] - bg[0]) + Math.abs(p[1] - bg[1]) + Math.abs(p[2] - bg[2]) > 150; };
  const rows = [];
  for (let y = y0; y < y1; y++) {
    let l = -1, r = -1;
    for (let x = x0; x < x1; x++) if (isInk(x, y)) { if (l < 0) l = x; r = x; }
    rows.push(l < 0 ? null : { l, r });
  }
  const lines = [];
  let cur = null, gap = 0;
  const maxGap = Math.round(4 * k); // разрыв между строками текста
  rows.forEach((row, i) => {
    if (row) {
      if (!cur) cur = { l: row.l, r: row.r, top: i, bottom: i };
      else { cur.l = Math.min(cur.l, row.l); cur.r = Math.max(cur.r, row.r); cur.bottom = i; }
      gap = 0;
    } else if (cur && ++gap > maxGap) { lines.push(cur); cur = null; gap = 0; }
  });
  if (cur) lines.push(cur);
  const left = rect.x * k, right = (rect.x + rect.width) * k;
  return lines
    .filter((ln) => ln.bottom - ln.top >= 4 * k * 0.5) // отсеять тонкие линии (рамка, курсор)
    .map((ln) => ({ leftGap: (ln.l - left) / k, rightGap: (right - ln.r) / k, top: (y0 + ln.top) / k, bottom: (y0 + ln.bottom) / k }));
}
